    "target": "DEMO-R1 (fictional cell-surface receptor)",
    "disease_context": "inflammatory skin disease-like assay; no patient-efficacy claim",
    "cell_context": "stimulated, Th17-enriched primary human CD4 T-cell culture (synthetic)",
    "intervention": "partial reduction of target expression; no claim of equivalence to activity blockade",
    "endpoint": "relative reduction in fraction of live CD4 T cells that are IL-17A positive",
    "endpoint_time_hours": 72,
    "assay_protocol_version": "mock-assay-v1"
  },
  "notice": "All target-specific data and source IDs are invented. No source ID denotes a published study. Sixteen records are not sixteen independent studies.",
